            if(!observationProbes.add(task.getString("id")))return;String taskId=task.getString("id"),runId=task.getString("runId"),execution=service.getString("operationId");int epoch=task.getInt("coordinatorEpoch");RunControl original=host.currentControl(taskId);assertNotNull(original);JSONObject originalBinding=binding(task),nativeContext=task.getJSONObject("teamProject"),serviceBinding=service.getJSONObject("receipt").getJSONObject("projectExecution");
