        JSONObject reviewer(JSONArray history)throws Exception {JSONObject manifest=null;Set<String> read=new HashSet<>();boolean submitted=false;for(int i=0;i<history.length();i++){JSONObject m=history.getJSONObject(i);if(!m.optString("role").equals("tool"))continue;JSONObject r;try{r=new JSONObject(m.optString("content"));}catch(Exception ignored){continue;}if(r.has("files")&&r.has("planHash"))manifest=r;if(r.has("artifactId")&&(r.has("body")||r.has("contentBase64")||r.optString("unit").equals("tombstone"))){read.add(r.getString("artifactId"));if(r.has("contentBase64"))assertEquals(r.getString("rangeSha256"),ProjectSources.sha256(java.util.Base64.getDecoder().decode(r.getString("contentBase64"))));}submitted|=r.optBoolean("savedForOriginalReview");}if(submitted)return text("独立实际读取两作者准确冻结字节，结构化意见已保存；不代替组合测试或主人批准。");if(manifest==null)return tool("team_review_manifest",new JSONObject());JSONArray todo=new JSONArray(),all=manifest.getJSONArray("files");assertEquals(expectedReviewFiles>0?expectedReviewFiles:byteChanges?5:2,all.length());for(int i=0;i<all.length();i++)if(!read.contains(all.getJSONObject(i).getString("artifactId")))todo.put(call("team_read_review_file",new JSONObject().put("artifactId",all.getJSONObject(i).getString("artifactId"))));if(todo.length()>0)return calls(todo);return tool("team_submit_review",new JSONObject().put("verdict","no_blocking_findings").put("summary","独立实际读完两个真实模块原件，符合准确导出值；最终组合仍需实际测试和构建，非真实provider质量验收。"));}
