        JSONObject authors(TaskStoreTeamWriteHost.WorkPlanPage page)throws Exception {for(int attempt=0;attempt<12;attempt++){JSONObject state=settled(),work=page.snapshot().getJSONObject("workPlan");boolean done=true;JSONArray items=work.getJSONArray("items");for(int i=0;i<items.length();i++)done&=items.getJSONObject(i).optString("status").equals("completed");if(done)return state;int pendingApprovals=approvePending();if(pendingApprovals==0)diagnose("authors_no_original_approval");assertTrue("only visible exact owner proposals unblock, not budget refill: "+work,pendingApprovals>0);for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);if(!item.optString("status").equals("completed")){TaskStore.TeamWorkReview review=page.reviewContinuation(item.getString("workItemId"),item.getInt("itemRevision"),item.getInt("ownerGeneration"));page.approveContinuation(review,review.view().getString("digest"));}}}throw new AssertionError("authors failed to converge "+page.snapshot());}
        JSONObject integrate(String review)throws Exception {for(int attempt=0;attempt<12;attempt++){progress("integration.attempt_"+attempt+".begin");JSONObject state=host.integrate(run,review,model.withModel("integrator"));progress("integration.attempt_"+attempt+".returned_"+state.optString("status"));coordinator.recordIntegration(run,state);if(state.optString("status").equals("completed"))return state;if(tasks.hasUnresolved(state.getString("taskId")))diagnose("integration_original_unknown");assertFalse("unknown is never replayed: "+state,tasks.hasUnresolved(state.getString("taskId")));int originalApprovals=approvePending();if(originalApprovals==0)diagnose("integration_no_original_approval");assertTrue("only native exact owner decisions unblock integration: "+state,originalApprovals>0);}throw new AssertionError("integrator failed to converge");}
        void diagnose(String tag)throws Exception {JSONArray all=tasks.list(),originals=new JSONArray();for(int i=0;i<all.length();i++)originals.put(tasks.get(all.getJSONObject(i).getString("id"),false));Path evidence=Path.of(System.getProperty("a25.evidence"));Files.createDirectories(evidence);Path out=evidence.resolve(tag+"-"+run+".json");Files.writeString(out,new JSONObject().put("team",coordinator.get(run)).put("tasks",originals).put("fixtureFailure",failure.get()==null?JSONObject.NULL:failure.get().toString()).toString());JSONArray checkpoints=new JSONArray();try(Cursor rows=db(tasks).rawQuery("SELECT task_id,run_id,epoch,status,checkpoint FROM runs",null)){while(rows.moveToNext()){JSONObject checkpoint=new JSONObject(rows.getString(4)),summary=new JSONObject().put("taskId",rows.getString(0)).put("runId",rows.getString(1)).put("epoch",rows.getInt(2)).put("status",rows.getString(3)).put("checkpointUtf8Bytes",rows.getString(4).getBytes(StandardCharsets.UTF_8).length).put("checkpoint",checkpoint);checkpoints.put(summary);}}Files.writeString(evidence.resolve(tag+"-"+run+"-original-checkpoints.json"),checkpoints.toString());System.out.println("C6_ORIGINAL_DIAGNOSTIC "+out);}
        public void close()throws Exception {
            progress("fixture.close.begin");try {
            Throwable pending=null;
            try { if(coordinator!=null){coordinator.close();for(String key:new String[]{"coordinator","members"}){var f=TeamCoordinator.class.getDeclaredField(key);f.setAccessible(true);assertTrue("original coordinator worker must exit",((ExecutorService)f.get(coordinator)).awaitTermination(10,TimeUnit.SECONDS));}} }catch(Throwable e){pending=e;}
            try { if(host!=null)host.close(); }catch(Throwable e){if(pending==null)pending=e;else pending.addSuppressed(e);}
            for(CapabilityPort observer:transientReadPorts)try{observer.close();}catch(Throwable e){if(pending==null)pending=e;else pending.addSuppressed(e);}
            try { if(local!=null)local.close(); }catch(Throwable e){if(pending==null)pending=e;else pending.addSuppressed(e);}
            if(server!=null)server.stop(0);ContextBudgetPolicy.installHostSource(c->null);
            if(pending!=null){System.out.println("C6_NATIVE_TEAM_UNCONFIRMED_RESOURCES_PRESERVED "+temp);throw new Exception("Original resource cleanup remains unconfirmed; no files or pending ledger were removed",pending);}
            if(tasks!=null)db(tasks).close();if(temp!=null)try(var walk=Files.walk(temp)){for(Path path:walk.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}
            progress("fixture.close.complete");}finally{diagnosticsClosed=true;if(diagnosticMonitor!=null)diagnosticMonitor.interrupt();}
        }

